export const VISUAL_ASSET_BY_ID = new Map(VISUAL_ASSETS.map((asset) => [asset.id, asset]));
export function visualAsset(id, kind) { const asset = VISUAL_ASSET_BY_ID.get(String(id || '')); return asset && (!kind || asset.kind === kind) ? asset : null; }
